type Delivery = { id:number; plan_id:number; client_id:number; channel:string; available_at:string; status:string; sent_at?:string; viewed_at?:string; confirmed_at?:string; feedback?:string };
type Client = { id:number; name:string; email:string; initials:string; goal:string; age:number; weight:number; height:number; fitness_level:string; condition:string; limitations:string; equipment:string; preferences:string; days_per_week:number; status:string; last_active:string; sessions?:Record<string,number>; plan?:{id:number;status:string;week_label:string}|null; delivery?:Delivery|null };
type ExerciseMedia = { id:number; name:string; image_url:string; owner_id?:number|null; created_at?:string; description?:string };
type Exercise = { name:string; sets:number; reps:string; intensity:string; rest:string; duration?:string; instructions:string; media?:ExerciseMedia[] };
type Workout = { id:string; day:string; title:string; focus:string; duration:number; exercises:Exercise[] };
type Plan = { id:number; week_label:string; status:string; rationale:string; workouts:Workout[] };
type Session = { id:number; title:string; scheduled_date:string; status:string; duration:number|null; difficulty:number|null; notes:string; performance:{exercise:string;sets:string;load:string}[] };
type Progress = { id:number; recorded_date:string; weight:number; waist:number; body_fat:number; squat_max:number; feedback:string };
type ClientDetail = { client:Client; plan:Plan|null; delivery:Delivery|null; sessions:Session[]; progress:Progress[]; analysis:{completion:number;avgDifficulty:number;suggestion:string} };
type CalendarSession = { id:number; client_id:number; client_name:string; client_initials:string; title:string; scheduled_date:string; start_time:string; training_type:string; status:'upcoming'|'completed'|'cancelled'|'missed'; duration:number; notes:string; recurrence_rule:string };

const statusLabel: Record<string,string> = { on_track:'On track', attention:'Needs attention', needs_plan:'Plan needed', missed:'Missed sessions' };
const deliveryLabel: Record<string,string> = { scheduled:'Plan scheduled', sent:'Plan sent', viewed:'Plan viewed', confirmed:'Plan confirmed' };
const deliveryTone = (delivery?: Delivery|null) => delivery?.status === 'confirmed' || delivery?.status === 'viewed' ? 'completed' : delivery?.status === 'scheduled' ? 'needs_plan' : delivery?.status === 'sent' ? 'upcoming' : 'needs_plan';

const exerciseTranslations: Record<string,string> = {
  'Back squat':'Stražnji čučanj','Box squat':'Čučanj na kutiju','Romanian deadlift':'Rumunjsko mrtvo dizanje','Reverse lunge':'Iskorak unatrag','Dumbbell bench press':'Potisak bučicama s klupe','Single-arm cable row':'Veslanje na sajli jednom rukom','Half-kneeling press':'Potisak iz poluklečećeg položaja','Kettlebell deadlift':'Mrtvo dizanje s girjom','Incline push-up':'Sklek na povišenju','Bike intervals':'Intervali na biciklu','Zone 2 cardio':'Kardio u zoni 2','Mobility flow':'Vježbe mobilnosti',
  'Controlled':'Kontrolirano','Moderate':'Umjereno','Easy':'Lagano','Conversational':'Razgovorni tempo','None':'Bez odmora','As needed':'Po potrebi','2 reps in reserve':'2 ponavljanja u rezervi','10 / side':'10 / strana','45 sec work':'45 s rada','90 sec':'90 s','75 sec easy':'75 s lagano','60 sec':'60 s','45 sec':'45 s',
};
const englishExerciseText = (value:string) => Object.entries(exerciseTranslations).find(([,croatian])=>croatian===value)?.[0] || value;
const localizeExerciseText = (value:string, language:'hr'|'en') => { const english=englishExerciseText(value); return language==='hr'?exerciseTranslations[english]||english:english; };
const localizeWeekLabel = (value:string, language:'hr'|'en') => {
  const months:Record<string,string>={Jan:'sij',Feb:'velj',Mar:'ožu',Apr:'tra',May:'svi',Jun:'lip',Jul:'srp',Aug:'kol',Sep:'ruj',Oct:'lis',Nov:'stu',Dec:'pro'};
  if (value==='Next week'||value==='Sljedeći tjedan') return language==='hr'?'Sljedeći tjedan':'Next week';
  const english=value==='Sljedeći tjedan'?'Next week':value;
  if(language==='hr') return Object.entries(months).reduce((label,[en,hr])=>label.replace(new RegExp(`\\b${en}\\b`,'gi'),hr),english);
  const croatian=value==='Sljedeći tjedan'?'Next week':value;
  return Object.entries(months).reduce((label,[en,hr])=>label.replace(new RegExp(`\\b${hr}\\b`,'gi'),en),croatian);
};

