function AddClient({onClose,onCreated}:{onClose:()=>void;onCreated:(c:Client)=>void}) {
  const { language }=useLanguage(); const [step,setStep]=useState(1); const [saving,setSaving]=useState(false); const [data,setData]=useState<Record<string,string>>({fitness_level:'Beginner',days_per_week:'3',language});
  const set=(k:string,v:string)=>setData(d=>({...d,[k]:v}));
  async function submit(e:FormEvent){e.preventDefault();if(step<2){setStep(2);return}setSaving(true);const r=await fetch(apiUrl('clients'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(r.ok)onCreated(await r.json());else setSaving(false)}
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal" onSubmit={submit}><div className="modal-title"><div><span>New client assessment</span><h2>{step===1?'Start with the basics':'Training profile'}</h2></div><button type="button" aria-label="Close" onClick={onClose}><X/></button></div><div className="steps"><i className="done">1</i><span className={step===2?'filled':''}/><i className={step===2?'done':''}>2</i><small>Step {step} of 2</small></div>
    {step===1?<div className="form-grid"><Field label="Full name"><input autoFocus required value={data.name||''} onChange={e=>set('name',e.target.value)} placeholder="Client name"/></Field><Field label="Email"><input type="email" value={data.email||''} onChange={e=>set('email',e.target.value)} placeholder="client@example.com"/></Field><Field label="Age"><input type="number" required value={data.age||''} onChange={e=>set('age',e.target.value)}/></Field><Field label="Fitness level"><select value={data.fitness_level} onChange={e=>set('fitness_level',e.target.value)}><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></Field><Field label="Weight (kg)"><input type="number" step=".1" required value={data.weight||''} onChange={e=>set('weight',e.target.value)}/></Field><Field label="Height (cm)"><input type="number" required value={data.height||''} onChange={e=>set('height',e.target.value)}/></Field><Field label="Client language" wide><select value={data.language} onChange={e=>set('language',e.target.value)}><option value="hr">Hrvatski</option><option value="en">English</option></select></Field><Field label="Primary goal" wide><input required value={data.goal||''} onChange={e=>set('goal',e.target.value)} placeholder="Build strength, improve mobility…"/></Field></div>:<div className="form-grid"><Field label="Current physical condition" wide><textarea autoFocus required value={data.condition||''} onChange={e=>set('condition',e.target.value)} placeholder="Current activity, recovery, general readiness"/></Field><Field label="Injuries or limitations" wide><textarea value={data.limitations||''} onChange={e=>set('limitations',e.target.value)} placeholder="Include movements that cause discomfort"/></Field><Field label="Available equipment"><input required value={data.equipment||''} onChange={e=>set('equipment',e.target.value)} placeholder="Full gym, dumbbells…"/></Field><Field label="Preferred workouts"><input required value={data.preferences||''} onChange={e=>set('preferences',e.target.value)} placeholder="Strength, cycling…"/></Field><Field label="Training days per week" wide><div className="day-picker">{[2,3,4,5].map(n=><button type="button" className={data.days_per_week===String(n)?'selected':''} onClick={()=>set('days_per_week',String(n))} key={n}>{n} days</button>)}</div></Field></div>}
    <div className="modal-actions">{step===2&&<button type="button" className="secondary" onClick={()=>setStep(1)}>Back</button>}<button className="primary" disabled={saving}>{step===1?'Continue':'Create client and plan'}<ChevronRight size={17}/></button></div></form></div>
}

function Field({label,wide=false,children}:{label:string;wide?:boolean;children:React.ReactNode}) { return <label className={wide?'field wide':'field'}><span>{label}</span>{children}</label> }

type AuthUser = { id:number; email:string; display_name:string; first_name:string; last_name:string; phone:string; profile_photo_url:string|null; trainer_bio:string; role:'admin'|'trainer'|'client'; client_id:number|null; preferred_language:'hr'|'en'; onboarding_completed:number; password_reset_required?:number; is_preview?:number };
const destinationFor = (user:Pick<AuthUser,'role'|'onboarding_completed'>) => !user.onboarding_completed && user.role !== 'admin' ? '/onboarding' : user.role === 'admin' ? '/admin' : user.role === 'client' ? '/client' : '/';

function Login() {
  const navigate=useNavigate(); const location=useLocation(); const {language,setLanguage}=useLanguage(); const [email,setEmail]=useState('trainer@letsdoit.app'); const [password,setPassword]=useState('Trainer2026!'); const [error,setError]=useState(''); const [saving,setSaving]=useState(false);
  useEffect(()=>{const params=new URLSearchParams(location.search);const code=params.get('code');const ssoError=params.get('sso_error');if(ssoError){setError('Google sign-in was not completed.');return;}if(!code)return;setSaving(true);fetch(apiUrl('auth/exchange'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})}).then(async response=>({ok:response.ok,data:await response.json()})).then(({ok,data})=>{if(!ok){setError(data.message||'Google sign-in expired.');setSaving(false);return;}localStorage.setItem('letsdoit-session',data.token);setLanguage(data.user.preferred_language==='en'?'en':'hr');navigate(destinationFor(data.user),{replace:true});}).catch(()=>{setError('Google sign-in could not be completed.');setSaving(false);});},[location.search,navigate,setLanguage]);
  async function submit(event:FormEvent){event.preventDefault();setSaving(true);setError('');const response=await fetch(apiUrl('auth/login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});const data=await response.json();setSaving(false);if(!response.ok){setError(data.message||'Unable to sign in.');return;}localStorage.setItem('letsdoit-session',data.token);setLanguage(data.user.preferred_language==='en'?'en':'hr');navigate(destinationFor(data.user),{replace:true});}
  const copy=language==='hr'?{eyebrow:'Dobro došli',title:'Vaš trening, na jednom mjestu',body:'Prijavite se za svoj osobni raspored, plan i napredak.',email:'E-pošta',password:'Lozinka',submit:'Prijavi se',demo:'Demo računi: trainer@letsdoit.app ili maya@example.com'}:{eyebrow:'Welcome back',title:'Your training, in one place',body:'Sign in to reach your personal schedule, plan, and progress.',email:'Email',password:'Password',submit:'Sign in',demo:'Demo accounts: trainer@letsdoit.app or maya@example.com'};
  return <main className="login-page"><section className="login-card"><Link className="portal-brand login-brand" to="/login"><Activity size={20}/>LetsDoIt</Link><div className="language-choice login-language"><button className={language==='hr'?'selected':''} onClick={()=>setLanguage('hr')}>Hrvatski</button><button className={language==='en'?'selected':''} onClick={()=>setLanguage('en')}>English</button></div><p className="eyebrow">{copy.eyebrow}</p><h1>{copy.title}</h1><p>{copy.body}</p><a className="google-button" href={apiUrl('auth/google')}>Continue with Google</a><div className="login-divider"><span>or</span></div><form onSubmit={submit}><Field label={copy.email}><input autoFocus type="email" value={email} onChange={event=>setEmail(event.target.value)} required/></Field><Field label={copy.password}><input type="password" value={password} onChange={event=>setPassword(event.target.value)} required/></Field>{error&&<p className="login-error">{error}</p>}<button className="primary" disabled={saving}>{copy.submit}<ChevronRight size={17}/></button></form><small>{copy.demo} · Trainer2026! / Client2026!</small></section></main>
}

function AuthGate({children,role}:{children:React.ReactNode;role:'admin'|'trainer'|'client'}) {
  const location=useLocation(); const [user,setUser]=useState<AuthUser|null|undefined>(undefined);
  useEffect(()=>{fetch(apiUrl('auth/me')).then(response=>response.ok?response.json():null).then(setUser).catch(()=>setUser(null));},[]);
  if(user===undefined)return <div className="loading-portal">Loading…</div>;
  if(!user)return <Navigate to="/login" replace state={{from:location.pathname}}/>;
  if(user.password_reset_required&&!user.is_preview)return <Navigate to="/change-password" replace/>;
  if(!user.onboarding_completed&&user.role!=='admin'&&!user.is_preview)return <Navigate to="/onboarding" replace/>;
  const allowed=user.role===role||(role==='trainer'&&user.role==='admin');
  if(!allowed)return <Navigate to={user.role==='admin'?'/admin':user.role==='client'?'/client':'/'} replace/>;
  return <>{children}</>;
}

function ChangePassword(){const {language}=useLanguage();const navigate=useNavigate();const [password,setPassword]=useState('');const [confirm,setConfirm]=useState('');const [error,setError]=useState('');const [saving,setSaving]=useState(false);async function submit(event:FormEvent){event.preventDefault();if(password!==confirm){setError(language==='hr'?'Lozinke se ne podudaraju.':'Passwords do not match.');return}setSaving(true);const response=await fetch(apiUrl('auth/change-password'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({new_password:password})});const result=await response.json();setSaving(false);if(!response.ok){setError(result.message||'Unable to change password.');return}localStorage.setItem('letsdoit-session',result.token);navigate(result.user.role==='admin'?'/admin':result.user.role==='client'?'/client':'/',{replace:true})}return <main className="login-page"><form className="login-card" onSubmit={submit}><Link className="portal-brand login-brand" to="/login"><Activity size={20}/>LetsDoIt</Link><p className="eyebrow">{language==='hr'?'Sigurnost računa':'Account security'}</p><h1>{language==='hr'?'Postavite novu lozinku':'Set a new password'}</h1><p>{language==='hr'?'Privremenu lozinku zamijenite osobnom lozinkom od najmanje 10 znakova.':'Replace the temporary password with a personal password of at least 10 characters.'}</p><Field label={language==='hr'?'Nova lozinka':'New password'}><input autoFocus minLength={10} type="password" value={password} onChange={event=>setPassword(event.target.value)} required/></Field><Field label={language==='hr'?'Ponovite lozinku':'Confirm password'}><input minLength={10} type="password" value={confirm} onChange={event=>setConfirm(event.target.value)} required/></Field>{error&&<p className="login-error">{error}</p>}<button className="primary" disabled={saving}>{language==='hr'?'Spremi novu lozinku':'Save new password'}</button></form></main>}

function PasswordGate({children}:{children:React.ReactNode}){const [user,setUser]=useState<AuthUser|null|undefined>(undefined);useEffect(()=>{fetch(apiUrl('auth/me')).then(response=>response.ok?response.json():null).then(setUser).catch(()=>setUser(null))},[]);if(user===undefined)return <div className="loading-portal">Loading…</div>;if(!user)return <Navigate to="/login" replace/>;if(!user.password_reset_required)return <Navigate to={destinationFor(user)} replace/>;return <>{children}</>}

function Onboarding() {
  const { language, setLanguage } = useLanguage();
  const navigate = useNavigate();
  const [user, setUser] = useState<AuthUser | null | undefined>(undefined);
  const [role, setRole] = useState<'trainer' | 'client' | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [form, setForm] = useState({ first_name:'', last_name:'', phone:'', profile_photo_url:'', preferred_language:language, basic_info:'', age:'', gender:'', height:'', weight:'', fitness_level:'Beginner', goal:'', limitations:'', days_per_week:'3', equipment:'' });
  const copy = language === 'hr' ? {
    step:'Korak', roleStep:'Odaberite svoju ulogu', roleBody:'Prilagodit ćemo vaš prostor onome što trebate raditi.', trainer:'Trener', client:'Klijent', trainerDescription:'Vodite klijente, izrađujte planove i pratite napredak.', clientDescription:'Pratite treninge, plan i vlastiti napredak.', changeRole:'Promijeni ulogu', trainerTitle:'Postavite svoj trenerski profil', trainerBody:'Ovi podaci pomažu izgraditi vaš osobni trenerski prostor.', clientTitle:'Dovršite početnu procjenu', clientBody:'Ovi podaci postaju dio vaše početne procjene i pomoći će pri izradi prvog plana treninga.', firstName:'Ime', lastName:'Prezime', photo:'Profilna fotografija', addPhoto:'Dodajte fotografiju', optional:'neobavezno', phone:'Broj telefona', preferredLanguage:'Željeni jezik', basicInfo:'Osnovne informacije o treneru', basicInfoHint:'Iskustvo, specijalizacije ili način rada…', age:'Dob', gender:'Spol', selectGender:'Odaberite', woman:'Žensko', man:'Muško', nonbinary:'Nebinarno', undisclosed:'Ne želim navesti', height:'Visina (cm)', weight:'Težina (kg)', fitnessLevel:'Razina kondicije', beginner:'Početnik', intermediate:'Srednja razina', advanced:'Napredna razina', goal:'Glavni fitness cilj', goalHint:'npr. povećati snagu i poboljšati mobilnost', limitations:'Ozljede ili fizička ograničenja', limitationsHint:'Navedite ozljede, bol ili ograničenja pokreta', days:'Željeni broj treninga tjedno', equipment:'Dostupna oprema', equipmentHint:'npr. puna teretana, bučice ili oprema kod kuće', finish:'Dovrši postavljanje', profileStep:'Podaci o profilu', assessmentStep:'Početna procjena', photoError:'Odaberite sliku manju od 2 MB.', submitError:'Provjerite obavezna polja i pokušajte ponovno.', complete:'Postavljanje računa', languageHr:'Hrvatski', languageEn:'English'
  } : {
    step:'Step', roleStep:'Choose your role', roleBody:'We’ll tailor your workspace to what you need to do.', trainer:'Trainer', client:'Client', trainerDescription:'Manage clients, create plans, and track progress.', clientDescription:'Follow your workouts, plan, and personal progress.', changeRole:'Change role', trainerTitle:'Set up your trainer profile', trainerBody:'These details help us create your personal coaching workspace.', clientTitle:'Complete your initial assessment', clientBody:'These details become part of your initial assessment and help create your first workout plan.', firstName:'First name', lastName:'Last name', photo:'Profile photo', addPhoto:'Add a photo', optional:'optional', phone:'Phone number', preferredLanguage:'Preferred language', basicInfo:'Basic trainer information', basicInfoHint:'Experience, specialties, or coaching approach…', age:'Age', gender:'Gender', selectGender:'Select an option', woman:'Woman', man:'Man', nonbinary:'Non-binary', undisclosed:'Prefer not to say', height:'Height (cm)', weight:'Weight (kg)', fitnessLevel:'Fitness level', beginner:'Beginner', intermediate:'Intermediate', advanced:'Advanced', goal:'Main fitness goal', goalHint:'e.g. build strength and improve mobility', limitations:'Injuries or physical limitations', limitationsHint:'Include injuries, pain, or movement limitations', days:'Preferred training days per week', equipment:'Available equipment', equipmentHint:'e.g. full gym, dumbbells, or home equipment', finish:'Complete setup', profileStep:'Profile details', assessmentStep:'Initial assessment', photoError:'Choose an image smaller than 2 MB.', submitError:'Check the required fields and try again.', complete:'Account setup', languageHr:'Hrvatski', languageEn:'English'
  };
  const setValue = (key: keyof typeof form, value: string) => setForm(values => ({ ...values, [key]: value }));
  const changeLanguage = (next: 'hr' | 'en') => { setLanguage(next); setValue('preferred_language', next); };
  useEffect(() => { fetch(apiUrl('auth/me')).then(response => response.ok ? response.json() : null).then(setUser).catch(() => setUser(null)); }, []);
  useEffect(() => {
    if (!user) return;
    const [first = '', ...rest] = user.display_name.trim().split(/\s+/);
    setForm(values => ({ ...values, first_name: values.first_name || user.first_name || first, last_name: values.last_name || user.last_name || rest.join(' '), phone: user.phone || '', profile_photo_url: user.profile_photo_url || '', preferred_language: user.preferred_language || language, basic_info: user.trainer_bio || '' }));
  }, [user]);
  const choosePhoto = (event: any) => {
    const file = event.target.files?.[0] as File | undefined;
    if (!file) return;
    if (!file.type.startsWith('image/') || file.size > 2 * 1024 * 1024) { setError(copy.photoError); event.target.value = ''; return; }
    const reader = new FileReader();
    reader.onload = () => setValue('profile_photo_url', String(reader.result || ''));
    reader.readAsDataURL(file);
  };
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!role) return;
    setSaving(true); setError('');
    const response = await fetch(apiUrl('auth/onboarding'), { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ ...form, role }) });
    const result = await response.json().catch(() => ({}));
    setSaving(false);
    if (!response.ok) { setError(copy.submitError); return; }
    setLanguage(result.user.preferred_language === 'en' ? 'en' : 'hr');
    navigate(destinationFor(result.user), { replace:true });
  }
  if (user === undefined) return <div className="loading-portal">Loading…</div>;
  if (!user) return <Navigate to="/login" replace/>;
  if (user.role === 'admin' || user.onboarding_completed) return <Navigate to={destinationFor(user)} replace/>;
  if (!role) return <main className="onboarding-page"><section className="onboarding-card"><div className="onboarding-top"><Link className="onboarding-brand" to="/login"><Activity size={21}/>LetsDoIt</Link><div className="onboarding-language"><button className={language === 'hr' ? 'active' : ''} onClick={() => changeLanguage('hr')}>HR</button><button className={language === 'en' ? 'active' : ''} onClick={() => changeLanguage('en')}>EN</button></div></div><p className="eyebrow">{copy.step} 1 / 3</p><h1>{copy.roleStep}</h1><p className="onboarding-intro">{copy.roleBody}</p><div className="onboarding-role-grid"><button type="button" className="onboarding-role" onClick={() => setRole('trainer')}><UserRound size={25}/><strong>{copy.trainer}</strong><span>{copy.trainerDescription}</span></button><button type="button" className="onboarding-role" onClick={() => setRole('client')}><Dumbbell size={25}/><strong>{copy.client}</strong><span>{copy.clientDescription}</span></button></div></section></main>;
  return <main className="onboarding-page"><form className="onboarding-card onboarding-form" onSubmit={submit}><div className="onboarding-top"><Link className="onboarding-brand" to="/login"><Activity size={21}/>LetsDoIt</Link><div className="onboarding-language"><button type="button" className={language === 'hr' ? 'active' : ''} onClick={() => changeLanguage('hr')}>HR</button><button type="button" className={language === 'en' ? 'active' : ''} onClick={() => changeLanguage('en')}>EN</button></div></div><button type="button" className="onboarding-back" onClick={() => setRole(null)}>‹ {copy.changeRole}</button><p className="eyebrow">{copy.step} {role === 'trainer' ? '2' : '2'} / 3 · {role === 'trainer' ? copy.profileStep : copy.assessmentStep}</p><h1>{role === 'trainer' ? copy.trainerTitle : copy.clientTitle}</h1><p className="onboarding-intro">{role === 'trainer' ? copy.trainerBody : copy.clientBody}</p><div className="onboarding-photo"><div className="onboarding-photo-preview">{form.profile_photo_url ? <img src={form.profile_photo_url} alt=""/> : <span>{form.first_name[0] || form.last_name[0] || '+'}</span>}</div><label className="onboarding-photo-upload"><input type="file" accept="image/*" onChange={choosePhoto}/><strong>{copy.addPhoto}</strong><small>{copy.photo} · {copy.optional}</small></label></div><div className="form-grid"><Field label={copy.firstName}><input autoFocus required value={form.first_name} onChange={event => setValue('first_name', event.target.value)}/></Field><Field label={copy.lastName}><input required value={form.last_name} onChange={event => setValue('last_name', event.target.value)}/></Field>{role === 'trainer' && <Field label={`${copy.phone} · ${copy.optional}`}><input type="tel" value={form.phone} onChange={event => setValue('phone', event.target.value)}/></Field>}<Field label={copy.preferredLanguage}><select value={form.preferred_language} onChange={event => changeLanguage(event.target.value as 'hr' | 'en')}><option value="hr">{copy.languageHr}</option><option value="en">{copy.languageEn}</option></select></Field>{role === 'trainer' ? <Field label={`${copy.basicInfo} · ${copy.optional}`} wide><textarea value={form.basic_info} placeholder={copy.basicInfoHint} onChange={event => setValue('basic_info', event.target.value)}/></Field> : <><Field label={copy.age}><input required type="number" min="13" max="120" value={form.age} onChange={event => setValue('age', event.target.value)}/></Field><Field label={copy.gender}><select required value={form.gender} onChange={event => setValue('gender', event.target.value)}><option value="">{copy.selectGender}</option><option value="woman">{copy.woman}</option><option value="man">{copy.man}</option><option value="nonbinary">{copy.nonbinary}</option><option value="prefer_not_to_say">{copy.undisclosed}</option></select></Field><Field label={copy.height}><input required type="number" min="100" max="250" value={form.height} onChange={event => setValue('height', event.target.value)}/></Field><Field label={copy.weight}><input required type="number" min="25" max="350" step=".1" value={form.weight} onChange={event => setValue('weight', event.target.value)}/></Field><Field label={copy.fitnessLevel}><select value={form.fitness_level} onChange={event => setValue('fitness_level', event.target.value)}><option value="Beginner">{copy.beginner}</option><option value="Intermediate">{copy.intermediate}</option><option value="Advanced">{copy.advanced}</option></select></Field><Field label={copy.days}><select value={form.days_per_week} onChange={event => setValue('days_per_week', event.target.value)}>{[2,3,4].map(days => <option value={days} key={days}>{days}</option>)}</select></Field><Field label={copy.goal} wide><input required value={form.goal} placeholder={copy.goalHint} onChange={event => setValue('goal', event.target.value)}/></Field><Field label={`${copy.limitations} · ${copy.optional}`} wide><textarea value={form.limitations} placeholder={copy.limitationsHint} onChange={event => setValue('limitations', event.target.value)}/></Field><Field label={copy.equipment} wide><textarea required value={form.equipment} placeholder={copy.equipmentHint} onChange={event => setValue('equipment', event.target.value)}/></Field></>}</div>{error && <p className="onboarding-error">{error}</p>}<div className="onboarding-actions"><span>{copy.step} 3 / 3 · {copy.complete}</span><button className="primary" disabled={saving}>{copy.finish}<ChevronRight size={17}/></button></div></form></main>;
}

function ClientPage({planOnly=false}:{planOnly?:boolean}) {
  const { language }=useLanguage(); const locale=language==='hr'?'hr-HR':'en-US'; const {clientId}=useParams(); const navigate=useNavigate(); const [data,setData]=useState<ClientDetail|null>(null); const [error,setError]=useState(''); const [tab,setTab]=useState<'overview'|'workouts'|'progress'>('overview'); const [logSession,setLogSession]=useState<Session|null>(null); const [progressOpen,setProgressOpen]=useState(false);
  const load=()=>fetch(apiUrl(`clients/${clientId}`)).then(r=>{if(!r.ok)throw Error();return r.json()}).then(setData).catch(()=>setError('This client profile could not be loaded.'));
  useEffect(()=>{load()},[clientId]);
  if(error)return <Shell active="clients"><div className="error-state page">{error} <button onClick={load}>Retry</button></div></Shell>;
  if(!data)return <Shell active="clients"><div className="page"><div className="profile-skeleton"/></div></Shell>;
  if(planOnly&&data.plan)return <PlanReview data={data} onReload={load}/>;
  const {client,plan,delivery,sessions,progress,analysis}=data; const latest=progress.at(-1); const previous=progress.at(-2);
  return <Shell active="clients"><div className="page profile-page"><button className="back-link" onClick={()=>navigate('/clients')}><ArrowLeft size={17}/>All clients</button><header className="profile-header"><div className={`avatar large tone-${client.id}`}>{client.initials}</div><div><div className="profile-name"><h1>{client.name}</h1><i className={`status ${client.status}`}>{statusLabel[client.status]}</i></div><p>{client.email} · {client.age} years · {client.fitness_level}</p><span className="goal-line"><Sparkles size={15}/>{client.goal}</span>{delivery&&<span className="delivery-chip"><Check size={14}/>{deliveryLabel[delivery.status]}{delivery.confirmed_at?' · Schedule confirmed':''}</span>}</div><div className="profile-actions"><Link className="secondary" to={`/client/${client.id}`}>Client view</Link><Link className="primary" to={`/clients/${client.id}/plan`}>Review weekly plan</Link></div></header>
    <div className="tabs"><button className={tab==='overview'?'active':''} onClick={()=>setTab('overview')}>Overview</button><button className={tab==='workouts'?'active':''} onClick={()=>setTab('workouts')}>Workouts</button><button className={tab==='progress'?'active':''} onClick={()=>setTab('progress')}>Progress</button></div>
    {tab==='overview'&&<><section className="summary-grid"><article><span>Weekly completion</span><strong>{analysis.completion}%</strong><div className="bar"><i style={{width:`${analysis.completion}%`}}/></div><small>{sessions.filter(s=>s.status==='completed').length} sessions completed</small></article><article><span>Current weight</span><strong>{latest?.weight||client.weight} kg</strong><small className="positive">{previous&&latest?`${(latest.weight-previous.weight).toFixed(1)} kg since last check-in`:'Baseline recorded'}</small></article><article><span>Squat best</span><strong>{latest?.squat_max||'—'} kg</strong><small className="positive">Personal record this month</small></article><article><span>Average difficulty</span><strong>{analysis.avgDifficulty || '—'}<em>/10</em></strong><small>From completed sessions</small></article></section>
      <section className="profile-columns"><div><div className="section-title"><div><h2>This week</h2><p>{plan?.week_label}</p></div><Link to={`/clients/${client.id}/plan`}>Edit plan</Link></div><div className="session-list">{sessions.slice(0,4).map(s=><button key={s.id} onClick={()=>s.status!=='missed'&&setLogSession(s)}><i className={`session-state ${s.status}`}>{s.status==='completed'?<Check/>:s.status==='missed'?<X/>:<Dumbbell/>}</i><span><strong>{s.title}</strong><small>{new Date(s.scheduled_date+'T12:00:00').toLocaleDateString(locale,{weekday:'long',month:'short',day:'numeric'})}</small></span><i className={`status ${s.status}`}>{s.status}</i><ChevronRight size={17}/></button>)}</div></div><div><div className="section-title"><div><h2>Coach insight</h2><p>Next week’s recommendation</p></div></div><article className="insight-card"><span><Sparkles size={18}/>Weekly analysis</span><p>{analysis.suggestion}</p><div><b>Based on</b><small>{analysis.completion}% completion · {analysis.avgDifficulty}/10 difficulty · recent feedback</small></div><Link to={`/clients/${client.id}/plan`}>Review adjustment <ChevronRight size={16}/></Link></article></div></section></>}
    {tab==='workouts'&&<section className="tab-panel"><div className="section-title"><div><h2>Workout history</h2><p>Completed and upcoming sessions</p></div></div><div className="history-list">{sessions.map(s=><button key={s.id} onClick={()=>setLogSession(s)}><span><i className={`session-state ${s.status}`}>{s.status==='completed'?<Check/>:<Dumbbell/>}</i><span><strong>{s.title}</strong><small>{s.scheduled_date}</small></span></span><span><b>{s.duration?`${s.duration} min`:'Not logged'}</b><i className={`status ${s.status}`}>{s.status}</i><ChevronRight size={17}/></span></button>)}</div></section>}
    {tab==='progress'&&<section className="tab-panel"><div className="section-title"><div><h2>Progress over time</h2><p>Measurements, strength, feedback, and assessment results</p></div><button className="primary" onClick={()=>setProgressOpen(true)}><Plus size={17}/>Add check-in</button></div><ProgressView rows={progress}/></section>}
  </div>{logSession&&<LogWorkout session={logSession} onClose={()=>setLogSession(null)} onSaved={()=>{setLogSession(null);load()}}/>}{progressOpen&&<ProgressModal clientId={client.id} onClose={()=>setProgressOpen(false)} onSaved={()=>{setProgressOpen(false);load()}}/>}</Shell>
}

function ClientWorkspace() {
  const {language,setLanguage,t}=useLanguage(); const locale=language==='hr'?'hr-HR':'en-US'; const [data,setData]=useState<any>(null); const [tab,setTab]=useState<'today'|'plan'|'calendar'|'progress'|'history'>('today'); const [workout,setWorkout]=useState<Session|null>(null); const [progressOpen,setProgressOpen]=useState(false); const [notice,setNotice]=useState(''); const [mediaPreview,setMediaPreview]=useState<ExerciseMedia|null>(null);
  const load=()=>fetch(apiUrl('client/me')).then(response=>response.ok?response.json():Promise.reject()).then(setData);
  useEffect(()=>{load().catch(()=>setNotice(language==='hr'?'Nije moguće učitati vaš prostor.':'Your workspace could not be loaded.'));},[]);
  async function logout(){await fetch(apiUrl('auth/logout'),{method:'POST'});localStorage.removeItem('letsdoit-session');location.assign('./login');}
  if(!data)return <div className="client-portal loading-portal">{notice||'Loading your training…'}</div>;
  const copy=language==='hr'?{today:'Danas',plan:'Tjedni plan',calendar:'Raspored',progress:'Napredak',history:'Povijest',hello:'Bok',next:'Sljedeći trening',none:'Danas nema zakazanog treninga',upcoming:'Nadolazeći treninzi',log:'Zapiši trening',done:'Završi trening',measure:'Dodaj mjerenje',logout:'Odjava',available:'Plan je dostupan',send:'Trener još nije objavio novi plan',photo:'Poveznica na fotografiju'}:{today:'Today',plan:'Weekly plan',calendar:'Schedule',progress:'Progress',history:'History',hello:'Hi',next:'Next workout',none:'No workout is scheduled for today',upcoming:'Upcoming workouts',log:'Log workout',done:'Complete workout',measure:'Add check-in',logout:'Sign out',available:'Your plan is ready',send:'Your coach has not published a new plan yet',photo:'Photo link'};
  const upcoming=data.sessions.filter((session:Session)=>session.status==='upcoming').sort((a:Session,b:Session)=>a.scheduled_date.localeCompare(b.scheduled_date)); const today=upcoming.find((session:Session)=>session.scheduled_date===new Date().toISOString().slice(0,10))||upcoming[0]; const visibleSessions=tab==='history'?data.sessions.filter((session:Session)=>session.status==='completed'):upcoming;
  return <div className="client-portal"><header><Link to="/client" className="portal-brand"><Activity size={19}/>LetsDoIt</Link><div className="portal-actions"><span>{data.client.name}</span><button onClick={()=>setLanguage(language==='hr'?'en':'hr')}>{language==='hr'?'EN':'HR'}</button><button onClick={logout}>{copy.logout}</button></div></header><main><p className="eyebrow">{copy.today}</p><h1>{copy.hello}, {data.client.name.split(' ')[0]}</h1><p className="portal-intro">{language==='hr'?'Ovo je vaš osobni prostor za trening, raspored i napredak.':'This is your personal space for training, schedule, and progress.'}</p><nav className="portal-tabs">{([['today',copy.today],['plan',copy.plan],['calendar',copy.calendar],['progress',copy.progress],['history',copy.history]] as const).map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</nav>
    {tab==='today'&&<><section className="portal-status"><span><Check size={18}/>{data.plan?copy.available:copy.send}</span><p>{data.plan?localizeWeekLabel(data.plan.week_label,language):''}</p></section><section className="client-today"><div><p className="eyebrow">{copy.next}</p><h2>{today?t(today.title):copy.none}</h2>{today&&<p>{new Date(today.scheduled_date+'T12:00:00').toLocaleDateString(locale,{weekday:'long',month:'long',day:'numeric'})} · {today.duration||0} min</p>}</div>{today&&<button className="primary" onClick={()=>setWorkout(today)}>{copy.log}<ChevronRight size={16}/></button>}</section><section className="portal-history"><h2>{copy.upcoming}</h2>{upcoming.slice(0,4).map((session:Session)=><div key={session.id}><i className="session-state upcoming"><Dumbbell/></i><span><strong>{t(session.title)}</strong><small>{new Date(session.scheduled_date+'T12:00:00').toLocaleDateString(locale,{weekday:'short',month:'short',day:'numeric'})}</small></span><button className="icon-action" aria-label={copy.log} onClick={()=>setWorkout(session)}><ChevronRight size={17}/></button></div>)}</section></>}
    {tab==='plan'&&(!data.plan?<section className="portal-empty"><Clock3 size={27}/><h2>{copy.send}</h2></section>:<section className="portal-workouts">{data.plan.workouts.map((item:Workout)=><article key={item.id}><div><span>{t(item.day)}</span><h2>{t(item.title)}</h2><p>{item.duration} min · {t(item.focus)}</p></div><ul>{item.exercises.map((exercise:Exercise,index:number)=>{const media=exercise.media?.[0];const name=localizeExerciseText(exercise.name,language);return <li className="client-exercise" key={`${exercise.name}-${index}`}>{media?<button type="button" className="client-exercise-media" onClick={()=>setMediaPreview({...media,description:exercise.instructions})} aria-label={language==='hr'?`Prikaži sliku vježbe ${name}`:`View ${name} image`}><img src={media.image_url} alt=""/><Maximize2 size={14}/></button>:<span className="client-exercise-placeholder"><Dumbbell size={18}/></span>}<div><strong>{name}</strong><span>{exercise.sets} × {localizeExerciseText(exercise.reps,language)} · {localizeExerciseText(exercise.intensity,language)} · {localizeExerciseText(exercise.rest,language)}</span><p>{t(exercise.instructions)}</p></div></li>})}</ul></article>)}</section>)}
    {tab==='calendar'&&<section className="portal-history"><h2>{copy.calendar}</h2>{upcoming.map((session:Session)=><div key={session.id}><i className="session-state upcoming"><CalendarDays/></i><span><strong>{session.title}</strong><small>{new Date(session.scheduled_date+'T12:00:00').toLocaleDateString(locale,{weekday:'long',month:'long',day:'numeric'})} · {(session as any).start_time}</small></span><i className="status upcoming">{language==='hr'?'zakazano':'scheduled'}</i></div>)}</section>}
    {tab==='progress'&&<section className="tab-panel"><div className="section-title"><div><h2>{copy.progress}</h2><p>{language==='hr'?'Mjerenja, osobni rekordi i povratne informacije.':'Measurements, personal records, and feedback.'}</p></div><button className="primary" onClick={()=>setProgressOpen(true)}><Plus size={17}/>{copy.measure}</button></div><ProgressView rows={data.progress}/></section>}
    {tab==='history'&&<section className="portal-history"><h2>{copy.history}</h2>{visibleSessions.map((session:Session)=><div key={session.id}><i className="session-state completed"><Check/></i><span><strong>{session.title}</strong><small>{session.scheduled_date} · {session.duration||0} min · {session.difficulty||'—'}/10</small></span><i className="status completed">{language==='hr'?'završeno':'completed'}</i></div>)}</section>}
  </main>{workout&&<ClientWorkoutLog session={workout} plan={data.plan} onClose={()=>setWorkout(null)} onSaved={()=>{setWorkout(null);setNotice(language==='hr'?'Trening je spremljen.':'Workout saved.');load();}}/>}{progressOpen&&<ClientProgressForm onClose={()=>setProgressOpen(false)} onSaved={()=>{setProgressOpen(false);load();}} photoLabel={copy.photo}/>} {mediaPreview&&<ExerciseMediaLightbox media={mediaPreview} onClose={()=>setMediaPreview(null)}/>}</div>
}

function ClientWorkoutLog({session,plan,onClose,onSaved}:{session:Session;plan:Plan|null;onClose:()=>void;onSaved:()=>void}) { const {language}=useLanguage(); const [duration,setDuration]=useState(String(session.duration||45)); const [difficulty,setDifficulty]=useState('6'); const [notes,setNotes]=useState(''); const [saving,setSaving]=useState(false); const workout=plan?.workouts.find(item=>item.title===session.title); const exercises=workout?.exercises||[]; const [records,setRecords]=useState<Record<string,{sets:string;reps:string;load:string}>>(()=>Object.fromEntries(exercises.map(item=>[item.name,{sets:String(item.sets),reps:item.reps,load:''}])));
  async function submit(event:FormEvent){event.preventDefault();setSaving(true);await fetch(apiUrl(`client/sessions/${session.id}/complete`),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({duration:Number(duration),difficulty:Number(difficulty),notes,performance:exercises.map(exercise=>({exercise:exercise.name,...records[exercise.name]}))})});setSaving(false);onSaved();}
  return <div className="modal-backdrop"><form className="modal compact" onSubmit={submit}><div className="modal-title"><div><span>{language==='hr'?'Zapis treninga':'Workout log'}</span><h2>{session.title}</h2></div><button type="button" aria-label="Close" onClick={onClose}><X/></button></div><div className="form-grid"><Field label={language==='hr'?'Trajanje u minutama':'Duration in minutes'}><input autoFocus type="number" required value={duration} onChange={event=>setDuration(event.target.value)}/></Field><Field label={language==='hr'?'Težina 1–10':'Difficulty 1–10'}><input type="number" min="1" max="10" required value={difficulty} onChange={event=>setDifficulty(event.target.value)}/></Field>{exercises.map(exercise=><div className="exercise-log" key={exercise.name}><strong>{exercise.name}</strong><input aria-label="Sets" placeholder={language==='hr'?'Serije':'Sets'} value={records[exercise.name]?.sets||''} onChange={event=>setRecords(rows=>({...rows,[exercise.name]:{...rows[exercise.name],sets:event.target.value}}))}/><input aria-label="Reps" placeholder={language==='hr'?'Ponavljanja':'Reps'} value={records[exercise.name]?.reps||''} onChange={event=>setRecords(rows=>({...rows,[exercise.name]:{...rows[exercise.name],reps:event.target.value}}))}/><input aria-label="Weight" placeholder={language==='hr'?'Težina':'Weight'} value={records[exercise.name]?.load||''} onChange={event=>setRecords(rows=>({...rows,[exercise.name]:{...rows[exercise.name],load:event.target.value}}))}/></div>)}<Field label={language==='hr'?'Bilješke za trenera':'Notes for your coach'} wide><textarea value={notes} onChange={event=>setNotes(event.target.value)}/></Field></div><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>{language==='hr'?'Odustani':'Cancel'}</button><button className="primary" disabled={saving}>{language==='hr'?'Završi trening':'Complete workout'}<Check size={16}/></button></div></form></div> }

function ClientProgressForm({onClose,onSaved,photoLabel}:{onClose:()=>void;onSaved:()=>void;photoLabel:string}) { const {language}=useLanguage(); const [data,setData]=useState<Record<string,string>>({}); async function submit(event:FormEvent){event.preventDefault();await fetch(apiUrl('client/progress'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});onSaved();} const field=(key:string,label:string)=><Field label={label}><input type="number" step=".1" value={data[key]||''} onChange={event=>setData(values=>({...values,[key]:event.target.value}))}/></Field>;return <div className="modal-backdrop"><form className="modal compact" onSubmit={submit}><div className="modal-title"><div><span>{language==='hr'?'Napredak':'Progress'}</span><h2>{language==='hr'?'Novi unos':'New check-in'}</h2></div><button type="button" aria-label="Close" onClick={onClose}><X/></button></div><div className="form-grid">{field('weight',language==='hr'?'Težina kg':'Weight kg')}{field('waist',language==='hr'?'Struk cm':'Waist cm')}{field('body_fat',language==='hr'?'Tjelesna mast %':'Body fat %')}{field('squat_max',language==='hr'?'Najbolji čučanj kg':'Best squat kg')}<Field label={photoLabel} wide><input type="url" placeholder="https://…" value={data.photo_url||''} onChange={event=>setData(values=>({...values,photo_url:event.target.value}))}/></Field><Field label={language==='hr'?'Kako se osjećate?':'How do you feel?'} wide><textarea value={data.feedback||''} onChange={event=>setData(values=>({...values,feedback:event.target.value}))}/></Field></div><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>{language==='hr'?'Odustani':'Cancel'}</button><button className="primary">{language==='hr'?'Spremi':'Save'}</button></div></form></div> }

function ClientView() {
  const { language }=useLanguage(); const locale=language==='hr'?'hr-HR':'en-US'; const {clientId}=useParams(); const [data,setData]=useState<ClientDetail|null>(null); const [feedback,setFeedback]=useState(''); const [confirmed,setConfirmed]=useState(false);
  const load=()=>fetch(apiUrl(`clients/${clientId}`)).then(r=>r.json()).then(setData);
  useEffect(()=>{load()},[clientId]);
  useEffect(()=>{if(data?.delivery && ['sent','viewed'].includes(data.delivery.status)) fetch(apiUrl(`deliveries/${data.delivery.id}/view`),{method:'POST'}).then(load);},[data?.delivery?.id]);
  if(!data)return <div className="client-portal loading-portal">Loading your plan…</div>;
  const {client,plan,delivery,sessions}=data; const unavailable=!delivery || delivery.status==='scheduled';
  async function confirm(){if(!delivery)return;await fetch(apiUrl(`deliveries/${delivery.id}/confirm`),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({feedback})});setConfirmed(true);load();}
  return <div className="client-portal"><header><Link to={`/clients/${client.id}`} className="portal-brand"><Activity size={19}/>LetsDoIt</Link><span>{client.name}</span></header><main><p className="eyebrow">Your training plan</p><h1>Week of {plan?.week_label}</h1><p className="portal-intro">Your coach prepared this plan around your current goals, equipment, and recovery.</p>{unavailable?<section className="portal-empty"><Clock3 size={27}/><h2>Your next plan is on its way</h2><p>It will be available {delivery?new Date(delivery.available_at).toLocaleString(locale,{weekday:'long',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'}):'once your coach publishes it'}.</p></section>:<><section className="portal-status"><span><Check size={18}/>Plan available</span><p>{delivery?.confirmed_at||confirmed?'You confirmed this schedule. Your coach has your note.':'Please review your week and confirm that the schedule works for you.'}</p></section><section className="portal-workouts">{plan?.workouts.map(w=><article key={w.id}><div><span>{w.day}</span><h2>{w.title}</h2><p>{w.duration} min · {w.focus}</p></div><ul>{w.exercises.map(e=><li key={e.name}><strong>{e.name}</strong><span>{e.sets} sets · {e.reps} · {e.intensity}</span></li>)}</ul></article>)}</section>{!delivery?.confirmed_at&&!confirmed&&<section className="confirm-card"><div><h2>Does this schedule work?</h2><p>Confirm your week or leave a note for your coach.</p></div><textarea value={feedback} onChange={e=>setFeedback(e.target.value)} placeholder="Optional feedback about this plan"/><button className="primary" onClick={confirm}>Confirm schedule <Check size={17}/></button></section>}<section className="portal-history"><h2>Recent sessions</h2>{sessions.slice(0,3).map(s=><div key={s.id}><i className={`session-state ${s.status}`}>{s.status==='completed'?<Check/>:<Dumbbell/>}</i><span><strong>{s.title}</strong><small>{s.scheduled_date}</small></span><i className={`status ${s.status}`}>{s.status}</i></div>)}</section></>}</main></div>
}

function ProgressView({rows}:{rows:Progress[]}) { const { language }=useLanguage(); const locale=language==='hr'?'hr-HR':'en-US'; const max=Math.max(...rows.map(r=>r.squat_max||0),1); return <div className="progress-layout"><article className="chart-card"><span>Strength trend · squat</span><div className="chart">{rows.map(r=><div key={r.id}><i style={{height:`${Math.max(15,(r.squat_max/max)*100)}%`}}/><b>{r.squat_max||'—'} kg</b><small>{new Date(r.recorded_date+'T12:00:00').toLocaleDateString(locale,{month:'short'})}</small></div>)}</div></article><article className="measure-card"><span>Latest measurements</span>{rows.length?<><div><b>Weight</b><strong>{rows.at(-1)!.weight} kg</strong></div><div><b>Waist</b><strong>{rows.at(-1)!.waist} cm</strong></div><div><b>Body fat</b><strong>{rows.at(-1)!.body_fat}%</strong></div><blockquote>“{rows.at(-1)!.feedback}”</blockquote></>:<p>No measurements yet.</p>}</article><article className="photo-card"><span>Progress photos</span><div className="photo-placeholders"><i>Jun</i><i>Jul</i><button aria-label="Add progress photo"><Plus/></button></div><small>Add photos privately with each check-in.</small></article></div> }

function PlanReview({data,onReload}:{data:ClientDetail;onReload:()=>void}) {
  const { language,t }=useLanguage(); const locale=language==='hr'?'hr-HR':'en-US'; const navigate=useNavigate();
  const [plan,setPlan]=useState(data.plan!); const [open,setOpen]=useState(0); const [saving,setSaving]=useState(false); const [saved,setSaved]=useState(false); const [sendOpen,setSendOpen]=useState(false); const [delivery,setDelivery]=useState<Delivery|null>(data.delivery); const [mediaPreview,setMediaPreview]=useState<ExerciseMedia|null>(null); const [mediaLibrary,setMediaLibrary]=useState<ExerciseMedia[]>([]);
  const copy=language==='hr'?{week:'Tjedni plan',review:'Pregled prije objave',intro:'Napravite završne izmjene, zatim odaberite kada će plan postati dostupan za',save:'Spremi promjene',publish:'Objavi plan',update:'Ažuriraj dostavu',available:'Dostupno',confirmed:'Klijent je potvrdio raspored',viewed:'Klijent je pregledao plan',workspace:'Dostupno u prostoru klijenta',change:'Promijeni',suggested:'Predloženo prema izvedbi ovog tjedna',approval:'Potreban je pregled trenera',days:'dana treninga',minutes:'planiranih minuta',tailored:'prilagođeno',level:'razini',exercises:'vježbi',progressed:'Napredovanje',maintained:'Zadržano',visual:'Vizual',exercise:'Vježba',sets:'Serije',reps:'Ponavljanja',intensity:'Težina / intenzitet',rest:'Odmor',exerciseName:'Naziv vježbe',repetitions:'Ponavljanja',weightIntensity:'Težina ili intenzitet',restPeriod:'Vrijeme odmora',saved:'Plan je spremljen'}:{week:'Weekly plan',review:'Review before publishing',intro:'Make any final changes, then choose when this plan becomes available to',save:'Save changes',publish:'Publish plan',update:'Update delivery',available:'Available',confirmed:'Client confirmed their schedule',viewed:'Client has viewed this plan',workspace:'Available in the client workspace',change:'Change',suggested:'Suggested from this week’s performance',approval:'Trainer review required',days:'training days',minutes:'planned minutes',tailored:'tailored to',level:'level',exercises:'exercises',progressed:'Progressed',maintained:'Maintained',visual:'Visual',exercise:'Exercise',sets:'Sets',reps:'Reps',intensity:'Weight / intensity',rest:'Rest',exerciseName:'Exercise name',repetitions:'Repetitions',weightIntensity:'Weight or intensity',restPeriod:'Rest period',saved:'Plan saved'};
  useEffect(()=>{fetch(apiUrl('exercise-media')).then(response=>response.ok?response.json():[]).then(setMediaLibrary).catch(()=>setMediaLibrary([]));},[]);
  function editExercise(wi:number,ei:number,key:keyof Exercise,value:string|number){setPlan(p=>({...p,workouts:p.workouts.map((w,i)=>i===wi?{...w,exercises:w.exercises.map((e,j)=>j===ei?{...e,[key]:value}:e)}:w)}))}
  function selectExercise(wi:number,ei:number,name:string){const template=exerciseLibrary.find(item=>item.name===name);if(!template)return;const {mediaName,...exercise}=template;const media=mediaLibrary.find(item=>englishExerciseText(item.name)===(mediaName||name));setPlan(p=>({...p,workouts:p.workouts.map((w,i)=>i===wi?{...w,exercises:w.exercises.map((e,j)=>j===ei?{...e,...exercise,media:media?[media]:[]}:e)}:w)}))}
  function setExerciseMedia(wi:number,ei:number,media:ExerciseMedia[]){setPlan(p=>({...p,workouts:p.workouts.map((w,i)=>i===wi?{...w,exercises:w.exercises.map((e,j)=>j===ei?{...e,media}:e)}:w)}))}
  async function save(){setSaving(true);await fetch(apiUrl(`plans/${plan.id}`),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:plan.status,workouts:plan.workouts})});setSaving(false);setSaved(true);setTimeout(()=>setSaved(false),2500)}
  async function publish(values:{channel:string;available_at:string}){await save();const response=await fetch(apiUrl(`plans/${plan.id}/delivery`),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});if(response.ok){setDelivery(await response.json());setPlan(p=>({...p,status:'assigned'}));setSendOpen(false);onReload();}}
  return <Shell active="clients"><div className="page plan-page"><button className="back-link" onClick={()=>navigate(`/clients/${data.client.id}`)}><ArrowLeft size={17}/>{data.client.name}</button><header className="plan-header"><div><p className="eyebrow">{copy.week} · {localizeWeekLabel(plan.week_label,language)}</p><h1>{copy.review}</h1><p>{copy.intro} {data.client.name.split(' ')[0]}.</p></div><div className="plan-actions"><button className="secondary" onClick={save} disabled={saving}>{copy.save}</button><button className="primary" onClick={()=>setSendOpen(true)}><Check size={18}/>{delivery?copy.update:copy.publish}</button></div></header>{delivery&&<div className="delivery-state"><i className={`status ${deliveryTone(delivery)}`}>{t(deliveryLabel[delivery.status])}</i><span>{delivery.status==='scheduled'?`${copy.available} ${new Date(delivery.available_at).toLocaleString(locale,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`:delivery.status==='confirmed'?copy.confirmed:delivery.status==='viewed'?copy.viewed:copy.workspace}</span><button onClick={()=>setSendOpen(true)}>{copy.change}</button></div>}<div className="plan-banner"><Sparkles size={20}/><div><strong>{copy.suggested}</strong><p>{t(data.analysis.suggestion)}</p></div><span>{copy.approval}</span></div>
    <section className="workout-editor"><div className="editor-head"><div><h2>{plan.workouts.length} {copy.days}</h2><p>{plan.workouts.reduce((n,w)=>n+w.duration,0)} {copy.minutes} · {copy.tailored} {t(data.client.fitness_level).toLowerCase()} {copy.level}</p></div></div>{plan.workouts.map((w,wi)=><article className="workout-card" key={w.id}><button className="workout-summary" onClick={()=>setOpen(open===wi?-1:wi)}><span className="day-box"><b>{t(w.day).slice(0,3)}</b><small>{t(w.focus)}</small></span><span><strong>{t(w.title)}</strong><small><Clock3 size={14}/>{w.duration} min · {w.exercises.length} {copy.exercises}</small></span><i className={`status ${wi<2?'completed':'upcoming'}`}>{wi<2?copy.progressed:copy.maintained}</i><ChevronDown className={open===wi?'rotate':''}/></button>{open===wi&&<div className="exercise-table"><div className="exercise-head"><span>{copy.visual}</span><span>{copy.exercise}</span><span>{copy.sets}</span><span>{copy.reps}</span><span>{copy.intensity}</span><span>{copy.rest}</span></div>{w.exercises.map((e,ei)=><div className="exercise-row" key={ei}><ExerciseMediaPicker exerciseName={localizeExerciseText(e.name,language)} media={e.media?.[0]} onChange={media=>setExerciseMedia(wi,ei,media)} onPreview={setMediaPreview}/><label><b>{ei+1}</b><select aria-label={copy.exerciseName} value={englishExerciseText(e.name)} onChange={x=>selectExercise(wi,ei,x.target.value)}>{!exerciseLibrary.some(item=>item.name===englishExerciseText(e.name))&&<option value={englishExerciseText(e.name)}>{localizeExerciseText(e.name,language)}</option>}{exerciseLibrary.map(item=><option key={item.name} value={item.name}>{localizeExerciseText(item.name,language)}</option>)}</select><small>{t(e.instructions)}</small></label><input aria-label={copy.sets} type="number" value={e.sets} onChange={x=>editExercise(wi,ei,'sets',Number(x.target.value))}/><input aria-label={copy.repetitions} value={localizeExerciseText(e.reps,language)} onChange={x=>editExercise(wi,ei,'reps',x.target.value)}/><input aria-label={copy.weightIntensity} value={localizeExerciseText(e.intensity,language)} onChange={x=>editExercise(wi,ei,'intensity',x.target.value)}/><input aria-label={copy.restPeriod} value={localizeExerciseText(e.rest,language)} onChange={x=>editExercise(wi,ei,'rest',x.target.value)}/></div>)}</div>}</article>)}</section>{saved&&<div className="toast"><Check size={17}/>{copy.saved}</div>}</div>{sendOpen&&<SendPlanModal clientName={data.client.name} onClose={()=>setSendOpen(false)} onSend={publish}/>} {mediaPreview&&<ExerciseMediaLightbox media={mediaPreview} onClose={()=>setMediaPreview(null)}/>}</Shell>
}

function SendPlanModal({clientName,count,onClose,onSend}:{clientName?:string;count?:number;onClose:()=>void;onSend:(values:{channel:string;available_at:string})=>Promise<void>}) { const [channel,setChannel]=useState('in_app'); const [available,setAvailable]=useState(''); const [sending,setSending]=useState(false); const label=clientName||`${count} clients`; async function submit(e:FormEvent){e.preventDefault();setSending(true);await onSend({channel,available_at:available?new Date(available).toISOString():new Date().toISOString()});setSending(false)} return <div className="modal-backdrop"><form className="modal compact" onSubmit={submit}><div className="modal-title"><div><span>Plan delivery</span><h2>Publish to {label}</h2></div><button type="button" aria-label="Close" onClick={onClose}><X/></button></div><div className="delivery-options"><label className={channel==='in_app'?'selected':''}><input type="radio" name="channel" value="in_app" checked={channel==='in_app'} onChange={e=>setChannel(e.target.value)}/><span><strong>In-app notification</strong><small>Publishes the plan directly in the client workspace.</small></span></label><label className={channel==='email_and_in_app'?'selected':''}><input type="radio" name="channel" value="email_and_in_app" checked={channel==='email_and_in_app'} onChange={e=>setChannel(e.target.value)}/><span><strong>Email and in-app</strong><small>In-app publishing works now. Email sends when an email service is connected.</small></span></label></div><Field label="Make available"><input autoFocus type="datetime-local" value={available} onChange={e=>setAvailable(e.target.value)}/></Field><p className="delivery-note">Leave the date empty to publish immediately. Clients can view the week, confirm their schedule, and leave feedback.</p><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={sending}>{available?'Schedule plan':'Publish now'} <ChevronRight size={16}/></button></div></form></div> }

function LogWorkout({session,onClose,onSaved}:{session:Session;onClose:()=>void;onSaved:()=>void}) { const [duration,setDuration]=useState(String(session.duration||'')); const [difficulty,setDifficulty]=useState(String(session.difficulty||6)); const [notes,setNotes]=useState(session.notes||''); async function submit(e:FormEvent){e.preventDefault();await fetch(apiUrl(`sessions/${session.id}`),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'completed',duration:Number(duration),difficulty:Number(difficulty),notes})});onSaved()} return <div className="modal-backdrop"><form className="modal compact" onSubmit={submit}><div className="modal-title"><div><span>Workout log</span><h2>{session.title}</h2></div><button type="button" aria-label="Close" onClick={onClose}><X/></button></div><div className="form-grid"><Field label="Duration (minutes)"><input autoFocus required type="number" value={duration} onChange={e=>setDuration(e.target.value)}/></Field><Field label="Difficulty (1–10)"><input required min="1" max="10" type="number" value={difficulty} onChange={e=>setDifficulty(e.target.value)}/></Field><Field label="Completed work" wide><textarea defaultValue={session.performance.map(p=>`${p.exercise}: ${p.sets} at ${p.load}`).join('\n')} placeholder="Sets, reps, and weight used"/></Field><Field label="Client notes" wide><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="How did the session feel?"/></Field></div><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary">Save workout</button></div></form></div> }

function ProgressModal({clientId,onClose,onSaved}:{clientId:number;onClose:()=>void;onSaved:()=>void}) { const [data,setData]=useState<Record<string,string>>({}); async function submit(e:FormEvent){e.preventDefault();await fetch(apiUrl(`clients/${clientId}/progress`),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});onSaved()} return <div className="modal-backdrop"><form className="modal compact" onSubmit={submit}><div className="modal-title"><div><span>Progress check-in</span><h2>Record new measurements</h2></div><button type="button" onClick={onClose} aria-label="Close"><X/></button></div><div className="form-grid">{[['weight','Weight (kg)'],['waist','Waist (cm)'],['body_fat','Body fat (%)'],['squat_max','Squat best (kg)']].map(([k,l],i)=><Field label={l} key={k}><input autoFocus={i===0} type="number" step=".1" value={data[k]||''} onChange={e=>setData(d=>({...d,[k]:e.target.value}))}/></Field>)}<Field label="Client feedback" wide><textarea value={data.feedback||''} onChange={e=>setData(d=>({...d,feedback:e.target.value}))} placeholder="Recovery, comfort, energy, confidence…"/></Field><Field label="Progress photo" wide><input className="file-input" type="file" accept="image/*"/></Field></div><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary">Save check-in</button></div></form></div> }

type ManagedAccount = { id:number; email:string; display_name:string; active:number; last_login:string|null; created_at:string; client_id?:number; client_count?:number; trainer_id?:number|null; trainer_name?:string|null; status?:string; role:'trainer'|'client' };
type AdminData = { trainers:ManagedAccount[]; clients:ManagedAccount[]; stats:{trainers:number;clients:number;active_clients:number;scheduled_sessions:number} };

function AdminPage(){
  const {language,setLanguage}=useLanguage(); const navigate=useNavigate();
  const [data,setData]=useState<AdminData|null>(null); const [error,setError]=useState(''); const [tab,setTab]=useState<'trainer'|'client'>('trainer'); const [query,setQuery]=useState(''); const [status,setStatus]=useState('all'); const [editing,setEditing]=useState<ManagedAccount|null|undefined>(undefined); const [trainerFilter,setTrainerFilter]=useState<number|null>(null); const [temporary,setTemporary]=useState<{name:string;password:string}|null>(null);
  const c=language==='hr'?{title:'Administracija',subtitle:'Upravljanje korisnicima i pristupom platformi',trainers:'Treneri',clients:'Klijenti',activeClients:'Aktivni klijenti',sessions:'Zakazani treninzi',addTrainer:'Dodaj trenera',addClient:'Dodaj klijenta',search:'Pretraži račune',all:'Svi računi',active:'Aktivni',inactive:'Neaktivni',unassigned:'Bez trenera',account:'Račun',assignment:'Dodjela',lastLogin:'Zadnja prijava',status:'Status',never:'Nikada',noResults:'Nema pronađenih računa',platform:'Trenerski prostor',signOut:'Odjava',language:'Jezik',showAll:'Prikaži sve klijente'}:{title:'Administration',subtitle:'Manage people and platform access',trainers:'Trainers',clients:'Clients',activeClients:'Active clients',sessions:'Scheduled sessions',addTrainer:'Add trainer',addClient:'Add client',search:'Search accounts',all:'All accounts',active:'Active',inactive:'Inactive',unassigned:'Unassigned',account:'Account',assignment:'Assignment',lastLogin:'Last login',status:'Status',never:'Never',noResults:'No accounts found',platform:'Trainer workspace',signOut:'Sign out',language:'Language',showAll:'Show all clients'};
  const load=()=>{setError('');fetch(apiUrl('admin/overview')).then(async r=>{if(!r.ok)throw Error();return r.json()}).then((value:AdminData)=>setData({...value,trainers:value.trainers.map(x=>({...x,role:'trainer'})),clients:value.clients.map(x=>({...x,role:'client'}))})).catch(()=>setError(language==='hr'?'Administracija se trenutačno ne može učitati.':'Administration could not be loaded.'))};
  useEffect(()=>{load()},[]);
  const accounts=(tab==='trainer'?data?.trainers:data?.clients)||[];
  const visible=accounts.filter(account=>`${account.display_name} ${account.email}`.toLowerCase().includes(query.toLowerCase())&&(status==='all'||(status==='active'&&account.active)||(status==='inactive'&&!account.active)||(status==='unassigned'&&account.role==='client'&&!account.trainer_id))&&(!trainerFilter||account.trainer_id===trainerFilter));
  async function logout(){await fetch(apiUrl('auth/logout'),{method:'POST'});localStorage.removeItem('letsdoit-session');navigate('/login',{replace:true});}
  async function updateAccount(account:ManagedAccount, values:Record<string,unknown>){await fetch(apiUrl(`admin/users/${account.id}`),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});load()}
  async function removeAccount(account:ManagedAccount){const prompt=language==='hr'?`Trajno izbrisati račun ${account.display_name}?`:`Permanently delete ${account.display_name}?`;if(!window.confirm(prompt))return;await fetch(apiUrl(`admin/users/${account.id}`),{method:'DELETE'});load()}
  async function resetPassword(account:ManagedAccount){const response=await fetch(apiUrl(`admin/users/${account.id}/reset-password`),{method:'POST'});const result=await response.json();if(response.ok)setTemporary({name:account.display_name,password:result.temporaryPassword})}
  async function preview(account:ManagedAccount){const response=await fetch(apiUrl(`admin/users/${account.id}/preview`),{method:'POST'});const result=await response.json();if(!response.ok)return;sessionStorage.setItem('letsdoit-admin-session',localStorage.getItem('letsdoit-session')||'');localStorage.setItem('letsdoit-session',result.token);window.location.assign(`${APP_BASE}${result.role==='client'?'/client':'/'}`)}
  const date=(value:string|null)=>value?new Date(value).toLocaleString(language==='hr'?'hr-HR':'en-US',{dateStyle:'medium',timeStyle:'short'}):c.never;
  return <div className="admin-shell"><aside className="admin-sidebar"><Link to="/admin" className="brand"><span className="brand-mark"><Activity size={21}/></span><span>LetsDoIt</span></Link><div className="admin-identity"><ShieldCheck size={19}/><div><strong>{c.title}</strong><span>zmilosevich@gmail.com</span></div></div><nav><button className={tab==='trainer'?'active':''} onClick={()=>{setTab('trainer');setTrainerFilter(null)}}><UserRound size={18}/>{c.trainers}</button><button className={tab==='client'?'active':''} onClick={()=>{setTab('client');setTrainerFilter(null)}}><Users size={18}/>{c.clients}</button><Link to="/"><LayoutDashboard size={18}/>{c.platform}</Link></nav><div className="admin-side-foot"><div><span>{c.language}</span><button className={language==='hr'?'active':''} onClick={()=>setLanguage('hr')}>HR</button><button className={language==='en'?'active':''} onClick={()=>setLanguage('en')}>EN</button></div><button onClick={logout}>{c.signOut}</button></div></aside><main><div className="admin-page"><header className="admin-header"><div><p className="eyebrow">LetsDoIt</p><h1>{c.title}</h1><p>{c.subtitle}</p></div><button className="primary" onClick={()=>setEditing(null)}><UserPlus size={17}/>{tab==='trainer'?c.addTrainer:c.addClient}</button></header>
    <section className="admin-stats"><Metric icon={<UserRound/>} label={c.trainers} value={String(data?.stats.trainers||0)} detail={language==='hr'?'Ukupno računa':'Total accounts'}/><Metric icon={<Users/>} label={c.clients} value={String(data?.stats.clients||0)} detail={language==='hr'?'Ukupno računa':'Total accounts'} tone="violet"/><Metric icon={<Check/>} label={c.activeClients} value={String(data?.stats.active_clients||0)} detail={language==='hr'?'Mogu se prijaviti':'Can sign in'} tone="success"/><Metric icon={<CalendarDays/>} label={c.sessions} value={String(data?.stats.scheduled_sessions||0)} detail={language==='hr'?'Nadolazeći termini':'Upcoming'} tone="warning"/></section>
    <section className="admin-directory"><div className="admin-tools"><div className="admin-tabs"><button className={tab==='trainer'?'active':''} onClick={()=>{setTab('trainer');setTrainerFilter(null)}}>{c.trainers} <span>{data?.stats.trainers||0}</span></button><button className={tab==='client'?'active':''} onClick={()=>setTab('client')}>{c.clients} <span>{data?.stats.clients||0}</span></button></div><div className="tools"><label className="search"><Search size={17}/><input aria-label={c.search} placeholder={c.search} value={query} onChange={event=>setQuery(event.target.value)}/></label><select value={status} onChange={event=>setStatus(event.target.value)}><option value="all">{c.all}</option><option value="active">{c.active}</option><option value="inactive">{c.inactive}</option>{tab==='client'&&<option value="unassigned">{c.unassigned}</option>}</select></div></div>
    {trainerFilter&&<div className="admin-filter-note"><span>{language==='hr'?'Prikaz klijenata odabranog trenera':'Showing this trainer’s clients'}</span><button onClick={()=>setTrainerFilter(null)}>{c.showAll}</button></div>}
    {error&&<div className="error-state">{error}<button onClick={load}>Retry</button></div>}{!data&&!error&&<div className="skeleton-list"><i/><i/><i/></div>}{data&&visible.length===0&&<div className="empty-state"><Users size={25}/><strong>{c.noResults}</strong></div>}
    {data&&visible.length>0&&<div className="admin-table"><div className="admin-table-head"><span>{c.account}</span><span>{c.assignment}</span><span>{c.lastLogin}</span><span>{c.status}</span><span/></div>{visible.map(account=><article className="admin-row" key={account.id}><div className="account-cell"><i className={`avatar tone-${account.id}`}>{account.display_name.split(/\s+/).map(x=>x[0]).join('').slice(0,2)}</i><span><strong>{account.display_name}</strong><small>{account.email}</small></span></div><div>{account.role==='trainer'?<button className="client-count" onClick={()=>{setTab('client');setTrainerFilter(account.id)}}>{account.client_count||0} {language==='hr'?'klijenata':'clients'}</button>:<span className={!account.trainer_name?'muted':''}>{account.trainer_name||c.unassigned}</span>}</div><span className="last-login">{date(account.last_login)}</span><button className={`account-status ${account.active?'enabled':'disabled'}`} onClick={()=>updateAccount(account,{active:!account.active})}><Power size={13}/>{account.active?c.active:c.inactive}</button><div className="row-actions"><button aria-label={language==='hr'?'Pregledaj kao korisnik':'Preview as user'} onClick={()=>preview(account)} disabled={!account.active}><Eye/></button><button aria-label={language==='hr'?'Uredi račun':'Edit account'} onClick={()=>setEditing(account)}><Edit3/></button><button aria-label={language==='hr'?'Resetiraj lozinku':'Reset password'} onClick={()=>resetPassword(account)}><KeyRound/></button><button className="danger" aria-label={language==='hr'?'Izbriši račun':'Delete account'} onClick={()=>removeAccount(account)}><Trash2/></button></div></article>)}</div>}</section></div></main>{editing!==undefined&&<AdminAccountModal account={editing} role={editing?.role||tab} trainers={data?.trainers||[]} onClose={()=>setEditing(undefined)} onSaved={(name,password)=>{setEditing(undefined);load();if(password)setTemporary({name,password})}}/>}{temporary&&<TemporaryPasswordModal {...temporary} onClose={()=>setTemporary(null)}/>}</div>
}

function AdminAccountModal({account,role,trainers,onClose,onSaved}:{account:ManagedAccount|null;role:'trainer'|'client';trainers:ManagedAccount[];onClose:()=>void;onSaved:(name:string,password?:string)=>void}){const {language}=useLanguage();const [name,setName]=useState(account?.display_name||'');const [email,setEmail]=useState(account?.email||'');const [trainerId,setTrainerId]=useState(String(account?.trainer_id||''));const [saving,setSaving]=useState(false);const [error,setError]=useState('');const isNew=!account;async function submit(event:FormEvent){event.preventDefault();setSaving(true);setError('');const response=await fetch(apiUrl(account?`admin/users/${account.id}`:'admin/users'),{method:account?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name:name,email,role,trainer_id:Number(trainerId)||null})});const result=await response.json();setSaving(false);if(!response.ok){setError(result.message||'Unable to save account.');return;}onSaved(name,result.temporaryPassword)}const title=language==='hr'?(isNew?`Dodaj ${role==='trainer'?'trenera':'klijenta'}`:'Uredi račun'):(isNew?`Add ${role}`:'Edit account');return <div className="modal-backdrop"><form className="modal compact admin-modal" onSubmit={submit}><div className="modal-title"><div><span>{role==='trainer'?(language==='hr'?'Trenerski račun':'Trainer account'):(language==='hr'?'Klijentski račun':'Client account')}</span><h2>{title}</h2></div><button type="button" aria-label="Close" onClick={onClose}><X/></button></div><div className="form-grid"><Field label={language==='hr'?'Ime i prezime':'Full name'} wide><input autoFocus required value={name} onChange={event=>setName(event.target.value)}/></Field><Field label={language==='hr'?'E-pošta':'Email'} wide><input type="email" required value={email} onChange={event=>setEmail(event.target.value)}/></Field>{role==='client'&&<Field label={language==='hr'?'Dodijeljeni trener':'Assigned trainer'} wide><select value={trainerId} onChange={event=>setTrainerId(event.target.value)}><option value="">{language==='hr'?'Bez dodjele':'Unassigned'}</option>{trainers.filter(x=>x.active).map(trainer=><option key={trainer.id} value={trainer.id}>{trainer.display_name}</option>)}</select></Field>}</div>{error&&<p className="login-error">{error}</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>{language==='hr'?'Odustani':'Cancel'}</button><button className="primary" disabled={saving}>{language==='hr'?'Spremi račun':'Save account'}</button></div></form></div>}

function TemporaryPasswordModal({name,password,onClose}:{name:string;password:string;onClose:()=>void}){const {language}=useLanguage();const [copied,setCopied]=useState(false);return <div className="modal-backdrop"><div className="modal compact password-modal" role="dialog" aria-modal="true" tabIndex={-1} autoFocus><div className="modal-title"><div><span>{language==='hr'?'Jednokratni prikaz':'Shown once'}</span><h2>{language==='hr'?'Privremena lozinka':'Temporary password'}</h2></div><button type="button" aria-label="Close" onClick={onClose}><X/></button></div><p>{language==='hr'?`Sigurno podijelite ovu lozinku s korisnikom ${name}. Morat će je promijeniti.`:`Share this password securely with ${name}. They will need to change it.`}</p><div className="password-value"><code>{password}</code><button className="secondary" onClick={()=>{navigator.clipboard.writeText(password);setCopied(true)}}>{copied?(language==='hr'?'Kopirano':'Copied'):(language==='hr'?'Kopiraj':'Copy')}</button></div><div className="modal-actions"><button className="primary" onClick={onClose}>{language==='hr'?'Gotovo':'Done'}</button></div></div></div>}

function PreviewExit(){const backup=sessionStorage.getItem('letsdoit-admin-session');if(!backup)return null;return <button className="preview-exit" onClick={()=>{localStorage.setItem('letsdoit-session',backup);sessionStorage.removeItem('letsdoit-admin-session');window.location.assign(`${APP_BASE}/admin`)}}><ShieldCheck size={15}/>Exit preview</button>}

export default function App(){useInterfaceTranslation();return <><PreviewExit/><Routes><Route path="/login" element={<Login/>}/><Route path="/onboarding" element={<Onboarding/>}/><Route path="/change-password" element={<PasswordGate><ChangePassword/></PasswordGate>}/><Route path="/admin" element={<AuthGate role="admin"><AdminPage/></AuthGate>}/><Route path="/client" element={<AuthGate role="client"><ClientWorkspace/></AuthGate>}/><Route path="/client/:clientId" element={<AuthGate role="trainer"><ClientView/></AuthGate>}/><Route path="/clients/:clientId/preview" element={<AuthGate role="trainer"><ClientView/></AuthGate>}/><Route path="/" element={<AuthGate role="trainer"><Dashboard/></AuthGate>}/><Route path="/clients" element={<AuthGate role="trainer"><ClientDirectory/></AuthGate>}/><Route path="/schedule" element={<AuthGate role="trainer"><SchedulePage/></AuthGate>}/><Route path="/reports" element={<AuthGate role="trainer"><ReportsPage/></AuthGate>}/><Route path="/profile" element={<AuthGate role="trainer"><TrainerProfile/></AuthGate>}/><Route path="/clients/:clientId" element={<AuthGate role="trainer"><ClientPage/></AuthGate>}/><Route path="/clients/:clientId/plan" element={<AuthGate role="trainer"><ClientPage planOnly/></AuthGate>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes></>}
